**`app.gauge_glyph`** picks the fill of the containers load gauges and of the
netdiag waterfall: `shade` (the default — `░` for fill and track alike, told
apart by colour) or `block` (`█` over a `░` track). `block` is an opt-in because
`█` is East Asian ambiguous width and overflows the gauge columns on a terminal
that draws it double-width. It is not derived from the locale: the locale says
how the process *measures*, not what the terminal *draws* (§3.96). It is applied
through `theme.SetGaugeGlyph` at startup, on a context switch and on every save,
and anything but `block` stays on the safe glyph.
func (m Model) withUsage(u agentusage.Usage, full bool) Model {
	m = m.withRows(u, full)
	m.agentsLoading, m.agentsErr = false, false
	return m
}

// withRows rebuilds the agents table from u without touching the loading and
// error states, so a red footer survives the rebuild.
func (m Model) withRows(u agentusage.Usage, full bool) Model {
	before := populationOf(m.agentTable.Items())
	selected, hadSelection := m.selectedAgentKey()
	cursor := m.agentTable.Cursor()

	rows := agentRows(u, m.agentsTree(), m.clock, m.prices)
	m.breakdown = buildBreakdown(u, agentRows(u, true, m.clock, m.prices))
	m.clampBreakdown()
	m.usage = u
	m.cost = m.prices.Session(u)
	m.agentTable.SetItems(rows)

	if full || !slices.Equal(before, populationOf(rows)) {
	segCount
)

// share is one part's exact claim on the bar: floor cells plus a remainder
// (in units of 1/total cell), and whether it is worth at least half a cell.
type share struct {
	index    int
	part     int64
	floor    int
	rem      *big.Int
	eligible bool
	}
	return cells
}

// newShare computes part p's exact claim on width cells out of total.
func newShare(index int, p int64, width int, total *big.Int) share {
	num := new(big.Int).Mul(big.NewInt(p), big.NewInt(int64(width)))
	q, r := new(big.Int).QuoRem(num, total, new(big.Int))
	s := share{index: index, part: p, rem: r, eligible: num.Lsh(num, 1).Cmp(total) >= 0}
	if s.eligible {
		s.floor = int(q.Int64())
	}
	return s
}

// giveByRemainder hands one extra cell to each eligible share, largest
// remainder first, while cells remain; it returns the cells still unplaced.
func giveByRemainder(cells []int, shares []share, remaining int) int {
	order := slices.DeleteFunc(slices.Clone(shares), func(s share) bool { return !s.eligible })
	slices.SortStableFunc(order, func(a, b share) int {
		if c := b.rem.Cmp(a.rem); c != 0 {
			return c
		}
		return cmp.Compare(b.part, a.part)
	})
	for _, s := range order {
		if remaining == 0 {
			break
		}
		cells[s.index]++
		remaining--
	}
	return remaining
}

